use demlik_code_graph::{project::{Collation,EdgeScope,load_cheap_project,load_edge_project,discover_package_roots},engine::tsgo::TsgoBinary,extract::{assemble::{NodeFields,assemble_graph,assemble_graph_with_reports},analysis::AnalysisOptions,functions::discover_functions},kinds::rules::NodeKindRules,smells::coupling::{value_edges,coupling_by_file,find_cycles,cross_boundary_edges,rank_modules,analyze_coupling},render::{smells::render_smells,analysis::render_cycles},schema::Thresholds};
use std::{path::Path,rc::Rc,cell::Cell};
fn main()->Result<(),Box<dyn std::error::Error>>{
 let args:Vec<_>=std::env::args().collect();let root=Path::new(&args[2]);let host=Rc::new(Cell::new(0usize));let borrowed=&host;
 let(graph,report,edges,cycles,groups,ranked,facts,text)={let c=Collation::try_node22_en_us()?;let loaded=load_cheap_project(root,None)?;let found=discover_functions(&loaded.source_files,&c)?.functions;assert!(found.iter().all(|f|loaded.source_files.iter().any(|u|Rc::ptr_eq(u,&f.unit))));let graph=if args[1]=="cheap"{assemble_graph(&loaded,Thresholds::default(),NodeFields::default(),&c)?}else{let edge=load_edge_project(root,EdgeScope::Package,root,None)?;let binary=TsgoBinary::from_native_preview_manifest(Path::new(&args[3]))?;assemble_graph_with_reports(&edge,Thresholds::default(),&binary,NodeFields::default(),Some(&AnalysisOptions{cross_runtime:false,kinds:false,reach:false,clusters:true,interface_width:false,kind_rules:&NodeKindRules::default(),repo_root:root}),None,&c)?};let before=graph.modules.iter().map(|m|m.file.as_str()).collect::<Vec<_>>();let roots=discover_package_roots(root,None);let report=analyze_coupling(&graph.modules,&roots,&c)?;let edges=value_edges(&graph.modules,&c)?;let cycles=find_cycles(&graph.modules,&c)?;let groups=cross_boundary_edges(&graph.modules,&roots,&c)?;let ranked=rank_modules(&graph.modules,&roots,&c)?;let facts=coupling_by_file(&graph.modules,&roots,&c)?;let text=render_cycles(&graph,false,false,&c)?;let _=render_smells(&graph,true,false,&c)?;assert_eq!(before,graph.modules.iter().map(|m|m.file.as_str()).collect::<Vec<_>>());borrowed.set(found.len());(graph,report,edges,cycles,groups,ranked,facts,text)};
 assert!(graph.modules.len()>2);assert_eq!(facts.len(),graph.modules.len());assert_eq!(report.coupling.len(),facts.len());assert_eq!(report.cycles.len(),cycles.len());assert_eq!(report.cross_boundary.len(),groups.len());assert_eq!(report.ranked.len(),ranked.len());assert!(host.get()>2);if args[1]=="cheap"{assert!(edges.is_empty());assert!(text.to_lossy().contains("pass did not run"));}else{assert!(!edges.is_empty());assert!(!cycles.is_empty());assert!(!groups.is_empty());assert!(!ranked.is_empty());}println!("original Rc/graph/modules + borrowed host; owned coupling facts survive Collation drop");Ok(())
}
